    constructor(C _c) { c = _c; }
    function run(address newManager) public {
        // caller is a ward on a fresh c; first deny ourselves
        c.deny(address(this));
        // now any auth-gated call must revert
        bool revertedAfterDeny;
        try c.file("investmentManager", newManager) { revertedAfterDeny = false; }
        catch { revertedAfterDeny = true; }
        // state unchanged: still old investmentManager
        address managerAfterDeny = address(c.investmentManager());
        // regain authorization and retry
        c.rely(address(this));
        c.file("investmentManager", newManager);
        address managerAfterFile = address(c.investmentManager());
        assert(
            revertedAfterDeny &&
            managerAfterDeny == managerAfterFile &&
            managerAfterFile == newManager
        );
    }
    receive() external payable {}
}

