contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 price) public {
        // As deployer, the test contract is a ward; updatePrice must succeed.
        c.updatePrice(price);
        assert(c.latestPrice() == price && c.lastPriceUpdate() == block.timestamp);

        // Give up authorization: updatePrice must now revert and leave state unchanged.
        c.deny(address(this));
        bool reverted;
        uint128 before = c.latestPrice();
        try c.updatePrice(price + 1) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.latestPrice() == before);

        // Regain authorization via rely from another ward? Not possible; instead check
        // rely by self is blocked too, and that wards reflects authorization state.
        bool relyReverted;
        try c.rely(address(this)) { relyReverted = false; } catch { relyReverted = true; }
        assert(relyReverted);
    }

    receive() external payable {}
}

