    function run(uint128 price, address attacker) public {
        // authorized path: deployer (this contract) is a ward
        c.updatePrice(price);
        uint128 stored = c.latestPrice();
        uint256 updated = c.lastPriceUpdate();
        // unauthorized path: a non-ward address
        bool reverted;
        uint128 before = c.latestPrice();
        try c.rely(attacker) { c.deny(attacker); } catch { reverted = true; }
        // attacker is not a ward; denying via c is done by us; instead simulate attacker by relying then denying is wrong.
        // Simplest: rely attacker, then let the check be done by a fresh unauthorized call impossible (no other sender).
